mapper.select:
SELECT a.config_id, a.param_code, a.remark, a.type, b.need_update, b.value_source, a.table_code, a.param_group_name, a.rel_param_codes, b.param_desc, b.param_val, b.param_name, b.sub_type FROM bt_dc_cfg a LEFT JOIN bt_dc_param b on a.param_code = b.param_code AND b.status_cd = '00A' WHERE a.status_cd = '00A'
AND a.type = #{type}
ORDER BY a.default_show DESC, a.sort DESC

SELECT param_desc, param_name, param_code, param_val, value_source, need_update, sub_type FROM bt_dc_param WHERE param_code IN
#{paramCode}
AND status_cd = '00A'
